from flask import Flask, jsonify, send_from_directory, request
from flask_cors import CORS
import yfinance as yf
import pandas as pd
from datetime import datetime, timedelta
import os
import re
import json
import concurrent.futures

app = Flask(__name__, static_folder='.')
CORS(app)

DEEPVAL_HTML_PATH = os.environ.get(
    'DEEPVAL_HTML_PATH',
    os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'DeepValuationBrasil', 'consenso_analistas.html')
)
SNAPSHOT_SCRIPT_RE = re.compile(r'<script id="snapshot" type="application/json">(.*?)</script>', re.S)


@app.after_request
def add_no_cache_headers(response):
    response.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
    response.headers['Pragma'] = 'no-cache'
    return response


@app.route('/')
def serve_html():
    return send_from_directory('.', 'index.html')


@app.route('/acoes')
def serve_stocks_html():
    return send_from_directory('.', 'acoes.html')


@app.route('/api/consenso-analistas')
def get_consenso_analistas():
    try:
        with open(DEEPVAL_HTML_PATH, encoding='utf-8') as f:
            html = f.read()
    except FileNotFoundError:
        return jsonify({'error': 'snapshot de consenso indisponível'}), 503

    match = SNAPSHOT_SCRIPT_RE.search(html)
    if not match:
        return jsonify({'error': 'snapshot de consenso malformado'}), 500

    try:
        snapshot = json.loads(match.group(1))
    except json.JSONDecodeError:
        return jsonify({'error': 'snapshot de consenso malformado'}), 500

    return jsonify(snapshot)

@app.route('/api/ibov')
def get_ibov_data():
    range_param = request.args.get('range', '1y')
    period_map = {
        '3mo': '3mo', '6mo': '6mo', '1y': '1y', '2y': '2y',
        'ytd': 'ytd', 'max': 'max'
    }
    period = period_map.get(range_param, '6mo')

    try:
        ibov = yf.Ticker('^BVSP')
        hist = ibov.history(period=period, interval='1d')
        hist = hist.dropna(subset=['Close'])

        if hist.empty:
            return jsonify({'error': 'No data returned from Yahoo Finance'}), 500

        hist = hist.reset_index()
        data = []
        for _, row in hist.iterrows():
            ts = row['Date']
            if isinstance(ts, pd.Timestamp):
                ts = ts.to_pydatetime()

            data.append({
                'date': ts.strftime('%Y-%m-%d'),
                'open': round(float(row['Open']), 2),
                'high': round(float(row['High']), 2),
                'low': round(float(row['Low']), 2),
                'close': round(float(row['Close']), 2),
                'volume': int(row['Volume'])
            })

        quote = ibov.history(period='5d', interval='1d')
        quote = quote.dropna(subset=['Close'])
        current_price = None
        change = None
        change_pct = None
        if not quote.empty:
            last = quote.iloc[-1]
            current_price = round(float(last['Close']), 2)
            if len(quote) > 1:
                prev_close = round(float(quote.iloc[-2]['Close']), 2)
                change = round(current_price - prev_close, 2)
                change_pct = round((change / prev_close) * 100, 2)
            else:
                change = 0
                change_pct = 0

        return jsonify({
            'data': data,
            'current': {
                'price': current_price or data[-1]['close'],
                'change': change,
                'changePercent': change_pct
            }
        })

    except Exception as e:
        return jsonify({'error': str(e)}), 500

